import { useEffect, useMemo, useState, type ReactNode } from "react";
import { useAuiState } from "@assistant-ui/react";

import {
  GREETING_ROTATION_MS,
  greetingCandidates,
  nextGreeting,
} from "../../lib/greeting";
import { isUnderserved } from "../../lib/odi";
import { useStudio } from "../../state/StudioContext";
import { BoltIcon, CaptureIcon, CompassIcon, SparkIcon } from "../icons";

function prefersReducedMotion(): boolean {
  return (
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

const PILL_ICONS: ReactNode[] = [
  <SparkIcon size={15} key="spark" />,
  <BoltIcon size={15} key="bolt" />,
  <CaptureIcon size={15} key="capture" />,
];

interface HeroPill {
  id: string;
  label: string;
  description?: string;
  icon: ReactNode;
  run: () => void;
  conversational?: boolean;
}

/**
 * The empty state.
 *
 * The starter prompts are the runtime's: `suggestions` on the external store is
 * the one place they are decided, so what the hero offers and what the thread
 * knows cannot drift apart.
 */
export function Hero() {
  const { displayName, canvas, llmHealth, openPanel, streaming, brief, openSetup, sendMessage } =
    useStudio();
  const suggestions = useAuiState((state) => state.thread.suggestions);
  const [now, setNow] = useState(() => new Date());
  const [currentId, setCurrentId] = useState<string | null>(null);

  const jobs = canvas?.jobs.length ?? 0;
  const outcomes = canvas?.outcomes.length ?? 0;
  const underserved = (canvas?.outcomes ?? []).filter((outcome) =>
    isUnderserved(outcome.opportunity_score),
  ).length;

  const candidates = useMemo(
    () =>
      greetingCandidates({
        now,
        displayName,
        jobCount: jobs,
        outcomeCount: outcomes,
        underservedCount: underserved,
        llmHealthy: llmHealth.healthy,
        productName: brief?.product_name,
        jobStatement: brief?.job_statement,
      }),
    [
      now,
      displayName,
      jobs,
      outcomes,
      underserved,
      llmHealth.healthy,
      brief?.product_name,
      brief?.job_statement,
    ],
  );

  const current = candidates.find((candidate) => candidate.id === currentId) ?? candidates[0];

  useEffect(() => {
    if (prefersReducedMotion()) {
      return;
    }
    const timer = window.setInterval(() => {
      if (typeof document !== "undefined" && document.hidden) {
        return;
      }
      setNow(new Date());
      setCurrentId((id) => nextGreeting(candidates, id ?? current?.id)?.id ?? null);
    }, GREETING_ROTATION_MS);
    return () => window.clearInterval(timer);
  }, [candidates, current?.id]);

  const pills: HeroPill[] = suggestions.map((suggestion, index) => ({
    id: `suggestion-${index}`,
    label: suggestion.title ?? suggestion.prompt,
    description: suggestion.label,
    icon: PILL_ICONS[index % PILL_ICONS.length],
    run: () => void sendMessage(suggestion.prompt),
    conversational: true,
  }));

  pills.push(
    jobs > 0 && llmHealth.healthy === false
      ? {
          id: "capture",
          label: "Capture what you heard",
          icon: <CaptureIcon size={15} />,
          run: () => openPanel("capture"),
        }
      : {
          id: "landscape",
          label: "Opportunity landscape",
          icon: <CompassIcon size={15} />,
          run: () => openPanel("landscape"),
        },
  );

  return (
    <div className="hero">
      <p className="hero__eyebrow">
        {brief?.product_name ? `Living Studio · ${brief.product_name}` : "Living Studio"}
      </p>
      <h1 className="hero__line" key={current?.id ?? "greeting"}>
        {current?.text ?? "Good morning"}
      </h1>
      <p className="hero__sub">
        {brief?.target_user
          ? `For ${brief.target_user}. Tell me where they get stuck, and we'll turn it into something you can defend.`
          : "Name what you're trying to win. I'll help you test whether it's worth it — and what to do next."}
      </p>
      <div className="hero__pills" aria-label="Suggested next steps">
        {pills.map((pill) => (
          <button
            key={pill.id}
            type="button"
            className={`suggestion${pill.conversational ? " suggestion--card" : ""}`}
            disabled={Boolean(pill.conversational && streaming)}
            onClick={pill.run}
          >
            {pill.icon}
            {pill.conversational ? (
              <span className="suggestion__copy">
                <span className="suggestion__title">{pill.label}</span>
                {pill.description ? (
                  <span className="suggestion__description">{pill.description}</span>
                ) : null}
              </span>
            ) : (
              pill.label
            )}
          </button>
        ))}
        <button
          type="button"
          className="suggestion suggestion--quiet"
          onClick={openSetup}
          title="Tell me about your product, audience, and job"
        >
          {brief ? "Edit context" : "Tell me what you're building"}
        </button>
      </div>
    </div>
  );
}

/**
 * The model picker in the composer's hint row.
 *
 * The list comes from the sidecar because the model server may only be
 * reachable from the host machine and is not necessarily CORS-open. Choosing a
 * model is the same write as the Settings field, so both stay in sync through
 * `StudioContext.saveSettings`.
 */

import { useEffect, useMemo, useRef, useState } from "react";

import { fetchModels } from "../../api/studioApi";
import { useStudio } from "../../state/StudioContext";
import { ChevronDownIcon } from "../icons";

export function ModelPicker() {
  const { settings, saveSettings, llmHealth, openPanel } = useStudio();
  const [open, setOpen] = useState(false);
  const [models, setModels] = useState<string[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [active, setActive] = useState(0);
  const [announcement, setAnnouncement] = useState("");

  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const optionRefs = useRef<(HTMLButtonElement | null)[]>([]);
  // One probe per backend+key, not one per open: reopening a menu the user has
  // already seen must not hit the model server again.
  const loadedFor = useRef<string | null>(null);
  const cacheKey = `${settings.base_url}\u0000${settings.api_key}`;

  // The reported list may not mention the model that is actually configured, so
  // the current one is always offered rather than silently disappearing.
  const options = useMemo(() => {
    // An empty answer is not a list to decorate: it means the backend told us
    // nothing, and offering only the configured name would hide that.
    if (!models?.length) {
      return [];
    }
    if (!settings.model_name || models.includes(settings.model_name)) {
      return models;
    }
    return [settings.model_name, ...models];
  }, [models, settings.model_name]);

  useEffect(() => {
    if (!open) {
      return;
    }
    const requestedFor = cacheKey;
    if (loadedFor.current === requestedFor) {
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);
    void fetchModels({ base_url: settings.base_url, api_key: settings.api_key })
      .then((result) => {
        if (cancelled) {
          return;
        }
        loadedFor.current = requestedFor;
        setModels(result.models);
        setError(result.error);
        // The list arrives after the menu opened, so the keyboard cursor is
        // still on the first row. Put it on the model in use instead, where the
        // reader expects to start.
        if (result.models.length > 0) {
          const listed = result.models.includes(settings.model_name)
            ? result.models
            : [settings.model_name, ...result.models];
          setActive(Math.max(listed.indexOf(settings.model_name), 0));
        }
      })
      .catch((failure: unknown) => {
        if (cancelled) {
          return;
        }
        setModels([]);
        setError(
          failure instanceof Error ? failure.message : "Could not reach the model server.",
        );
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [open, cacheKey, settings.base_url, settings.api_key, settings.model_name]);

  // Clicking anywhere else is a dismissal, not a selection.
  useEffect(() => {
    if (!open) {
      return;
    }
    function onPointerDown(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  // Move focus onto the current option when the list appears, so a keyboard
  // user lands inside it instead of having to Tab from the trigger.
  useEffect(() => {
    if (!open || options.length === 0) {
      return;
    }
    optionRefs.current[active]?.focus();
  }, [open, active, options.length]);

  function openMenu(position: "selected" | "last") {
    removeErrorToRetry();
    const selected = Math.max(options.indexOf(settings.model_name), 0);
    setActive(position === "last" ? Math.max(options.length - 1, 0) : selected);
    setOpen(true);
  }

  // A previous failure must not make reopening look cached.
  function removeErrorToRetry() {
    if (loadedFor.current !== null && error) {
      loadedFor.current = null;
    }
  }

  function choose(model: string) {
    if (model !== settings.model_name) {
      saveSettings({ ...settings, model_name: model });
      setAnnouncement(`Model set to ${model}`);
    }
    setOpen(false);
    triggerRef.current?.focus();
  }

  function onMenuKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") {
      event.preventDefault();
      setOpen(false);
      triggerRef.current?.focus();
      return;
    }
    if (event.key === "Tab") {
      setOpen(false);
      return;
    }
    // With no options the menu holds plain content (the explanation and its
    // Settings button); those keys belong to whatever has focus there.
    if (options.length === 0) {
      return;
    }

    switch (event.key) {
      case "ArrowDown":
      case "ArrowUp": {
        event.preventDefault();
        const delta = event.key === "ArrowDown" ? 1 : -1;
        setActive((index) => (index + delta + options.length) % options.length);
        return;
      }
      case "Home":
        event.preventDefault();
        setActive(0);
        return;
      case "End":
        event.preventDefault();
        setActive(Math.max(options.length - 1, 0));
        return;
      case "Enter":
      case " ": {
        const model = options[active];
        if (model) {
          event.preventDefault();
          choose(model);
        }
        return;
      }
      default:
        return;
    }
  }

  const offline = llmHealth.healthy === false;

  return (
    <div className="model-picker" ref={rootRef}>
      <button
        ref={triggerRef}
        type="button"
        className={`model-picker__trigger${offline ? " is-offline" : ""}`}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={`${offline ? "Model server offline. " : ""}Model: ${
          settings.model_name || "none configured"
        }. Choose a model`}
        title={offline ? "Model server offline — the last choice is still shown" : settings.model_name}
        onClick={() => (open ? setOpen(false) : openMenu("selected"))}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            openMenu(event.key === "ArrowDown" ? "selected" : "last");
          }
          if (event.key === "Escape" && open) {
            event.preventDefault();
            setOpen(false);
          }
        }}
      >
        <span className="model-picker__label">Model</span>
        <span className="model-picker__value">{settings.model_name || "Not set"}</span>
        <ChevronDownIcon size={13} />
      </button>

      {open ? (
        <div className="model-picker__menu" onKeyDown={onMenuKeyDown}>
          {loading ? (
            <p className="model-picker__state" role="status">
              Looking for models…
            </p>
          ) : options.length > 0 ? (
            <>
              {/* Only options live inside the listbox; a note beside it would
                  be read as an item. */}
              <div role="listbox" aria-label="Choose a model">
                {options.map((model, index) => {
                  const selected = model === settings.model_name;
                  return (
                    <button
                      key={model}
                      ref={(element) => {
                        optionRefs.current[index] = element;
                      }}
                      type="button"
                      role="option"
                      aria-selected={selected}
                      tabIndex={index === active ? 0 : -1}
                      className={`model-picker__option${selected ? " is-selected" : ""}`}
                      onClick={() => choose(model)}
                    >
                      <span className="model-picker__option-name">{model}</span>
                      {selected ? <span className="model-picker__check">Current</span> : null}
                    </button>
                  );
                })}
              </div>
              {error ? <p className="model-picker__note">{error}</p> : null}
            </>
          ) : (
            <div className="model-picker__state" role="status">
              <p>{error ?? "The model server reported no models."}</p>
              <button
                type="button"
                className="quiet-action"
                onClick={() => {
                  setOpen(false);
                  openPanel("settings");
                }}
              >
                Model settings
              </button>
            </div>
          )}
        </div>
      ) : null}

      <span className="sr-only" role="status">
        {announcement}
      </span>
    </div>
  );
}

import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { ModelPicker } from "./ModelPicker";

const harness = vi.hoisted(() => ({
  state: {
    settings: {
      base_url: "http://llm/v1",
      api_key: "k",
      model_name: "alpha",
      mcp_url: "http://mcp",
    },
    saveSettings: vi.fn(),
    llmHealth: { healthy: true, message: "ok" },
    openPanel: vi.fn(),
  },
}));

vi.mock("../../state/StudioContext", () => ({
  useStudio: () => harness.state,
}));

const api = vi.hoisted(() => ({ fetchModels: vi.fn() }));

vi.mock("../../api/studioApi", () => ({
  fetchModels: api.fetchModels,
}));

function trigger() {
  return screen.getByRole("button", { name: /Model: alpha/ });
}

describe("ModelPicker", () => {
  beforeEach(() => {
    api.fetchModels.mockReset();
    harness.state.saveSettings.mockReset();
    harness.state.openPanel.mockReset();
    harness.state.llmHealth = { healthy: true, message: "ok" };
  });

  it("lists what the backend serves and marks the current model", async () => {
    api.fetchModels.mockResolvedValue({ models: ["alpha", "beta"], error: null });
    render(<ModelPicker />);

    fireEvent.click(trigger());

    const alpha = await screen.findByRole("option", { name: /alpha/ });
    expect(alpha.getAttribute("aria-selected")).toBe("true");
    expect(screen.getByRole("option", { name: /beta/ }).getAttribute("aria-selected")).toBe(
      "false",
    );
  });

  it("saves the chosen model and closes the menu", async () => {
    api.fetchModels.mockResolvedValue({ models: ["alpha", "beta"], error: null });
    render(<ModelPicker />);

    fireEvent.click(trigger());
    fireEvent.click(await screen.findByRole("option", { name: /beta/ }));

    expect(harness.state.saveSettings).toHaveBeenCalledWith(
      expect.objectContaining({ model_name: "beta" }),
    );
    await waitFor(() => expect(screen.queryByRole("listbox")).toBeNull());
  });

  it("moves with the arrow keys and selects with Enter", async () => {
    api.fetchModels.mockResolvedValue({ models: ["alpha", "beta"], error: null });
    render(<ModelPicker />);

    fireEvent.click(trigger());
    await screen.findByRole("option", { name: /beta/ });

    fireEvent.keyDown(document.activeElement as Element, { key: "ArrowDown" });
    fireEvent.keyDown(document.activeElement as Element, { key: "Enter" });

    expect(harness.state.saveSettings).toHaveBeenCalledWith(
      expect.objectContaining({ model_name: "beta" }),
    );
  });

  it("closes on Escape and returns focus to the trigger", async () => {
    api.fetchModels.mockResolvedValue({ models: ["alpha"], error: null });
    render(<ModelPicker />);

    fireEvent.click(trigger());
    const option = await screen.findByRole("option", { name: /alpha/ });

    fireEvent.keyDown(option, { key: "Escape" });

    await waitFor(() => expect(screen.queryByRole("listbox")).toBeNull());
    expect(document.activeElement).toBe(trigger());
  });

  it("keeps the configured model selectable when the backend omits it", async () => {
    api.fetchModels.mockResolvedValue({ models: ["beta"], error: null });
    render(<ModelPicker />);

    fireEvent.click(trigger());

    const alpha = await screen.findByRole("option", { name: /alpha/ });
    expect(alpha.getAttribute("aria-selected")).toBe("true");
  });

  it("explains an unreachable model server and offers Settings", async () => {
    api.fetchModels.mockResolvedValue({
      models: [],
      error: "connection_error: connection refused",
    });
    render(<ModelPicker />);

    fireEvent.click(trigger());

    expect(await screen.findByText(/connection refused/)).toBeTruthy();
    fireEvent.click(screen.getByRole("button", { name: "Model settings" }));
    expect(harness.state.openPanel).toHaveBeenCalledWith("settings");
  });

  it("probes once per backend, not once per open", async () => {
    api.fetchModels.mockResolvedValue({ models: ["alpha", "beta"], error: null });
    render(<ModelPicker />);

    fireEvent.click(trigger());
    await screen.findByRole("option", { name: /beta/ });
    fireEvent.click(trigger());
    fireEvent.click(trigger());

    await waitFor(() => expect(screen.getByRole("listbox")).toBeTruthy());
    expect(api.fetchModels).toHaveBeenCalledTimes(1);
  });
});

